import{_ as a,o,c as t,a5 as n}from"./chunks/framework.DtspaGiy.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),r={name:"guide/faq.md"};function s(d,e,h,i,l,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="macos-says-blank-cannot-be-opened-or-is-damaged" tabindex="-1">macOS says Blank &quot;cannot be opened&quot; or &quot;is damaged&quot; <a class="header-anchor" href="#macos-says-blank-cannot-be-opened-or-is-damaged" aria-label="Permalink to &quot;macOS says Blank &quot;cannot be opened&quot; or &quot;is damaged&quot;&quot;">​</a></h2><p>Blank is not notarized by Apple. See <a href="./install#macos">Install → macOS</a> for how to allow it.</p><h2 id="where-are-my-documents-stored" tabindex="-1">Where are my documents stored? <a class="header-anchor" href="#where-are-my-documents-stored" aria-label="Permalink to &quot;Where are my documents stored?&quot;">​</a></h2><p>Files you save are ordinary markdown files wherever you saved them. On top of that, Blank keeps every open tab in its own app storage, unsaved changes included, and restores them on the next start, so closing the window doesn&#39;t lose anything. <code>Mod</code> <code>N</code> opens a new tab and leaves the others as they are. This is not a backup, though: a tab you close with <strong>Don&#39;t save</strong> is gone, so save what you want to keep.</p><h2 id="why-did-blank-change-what-i-typed" tabindex="-1">Why did Blank change what I typed? <a class="header-anchor" href="#why-did-blank-change-what-i-typed" aria-label="Permalink to &quot;Why did Blank change what I typed?&quot;">​</a></h2><p>That&#39;s <a href="./autocorrect">autocorrect</a>. Press <code>Mod</code> <code>Z</code> right away to undo a single correction, or <a href="./configuration#autocorrect">turn a group off</a>.</p><h2 id="the-quotes-look-wrong-for-my-language" tabindex="-1">The quotes look wrong for my language <a class="header-anchor" href="#the-quotes-look-wrong-for-my-language" aria-label="Permalink to &quot;The quotes look wrong for my language&quot;">​</a></h2><p>Quotes follow the language at the bottom right. Press <code>Mod</code> <code>Alt</code> <code>L</code> to <a href="./autocorrect#language">choose yours</a>.</p><h2 id="does-blank-check-my-spelling" tabindex="-1">Does Blank check my spelling? <a class="header-anchor" href="#does-blank-check-my-spelling" aria-label="Permalink to &quot;Does Blank check my spelling?&quot;">​</a></h2><p>If you want it to: press <code>Mod</code> <code>Alt</code> <code>S</code>. See <a href="./spelling">Spell check</a>.</p><h2 id="does-blank-send-my-text-anywhere" tabindex="-1">Does Blank send my text anywhere? <a class="header-anchor" href="#does-blank-send-my-text-anywhere" aria-label="Permalink to &quot;Does Blank send my text anywhere?&quot;">​</a></h2><p>No. There&#39;s no account, and nothing you write leaves your computer. Blank keeps a <a href="#log">log</a> of what went wrong, on your computer only. Blank downloads two things from the internet: a <a href="./spelling#languages">spell check dictionary</a> when you check a language that doesn&#39;t come with Blank, and the images from the web that your documents show and that your PDF and Word exports include.</p><h2 id="can-i-use-the-mouse" tabindex="-1">Can I use the mouse? <a class="header-anchor" href="#can-i-use-the-mouse" aria-label="Permalink to &quot;Can I use the mouse?&quot;">​</a></h2><p>Yes, though every command also has a key. You can click to place the cursor, select text and drag it somewhere else, click a header or footer on the page to change it or point at a margin to add one, and <code>Mod</code> + Click a link to open it. The <a href="./writing#toolbar">toolbar</a> formats and inserts with a click, the <a href="./writing#tabs">tabs</a> switch, close and move with the mouse, and <a href="./tables">tables</a> have handles for it too.</p><p>On Linux, middle-click pastes as in your other apps: the text you select in Blank is the one a middle click pastes elsewhere, and a middle click in Blank pastes the text you selected last, in Blank or in any other app, right where you click. It comes in as plain text.</p><h2 id="can-i-edit-a-word-document-with-blank" tabindex="-1">Can I edit a Word document with Blank? <a class="header-anchor" href="#can-i-edit-a-word-document-with-blank" aria-label="Permalink to &quot;Can I edit a Word document with Blank?&quot;">​</a></h2><p>You can open it with <code>Mod</code> <code>O</code>: Blank turns it into a markdown document and leaves the Word file as it is. When you&#39;re done, save it as markdown with <code>Mod</code> <code>S</code>, or send it back as a Word document with <code>Mod</code> <code>Alt</code> <code>W</code>. Blank never writes markdown into a .docx, so the original can&#39;t get lost by accident. See <a href="./files#back-and-forth">Back and forth with Word users</a> for how it works and what comes along.</p><h2 id="which-open-source-software-does-blank-use" tabindex="-1">Which open source software does Blank use? <a class="header-anchor" href="#which-open-source-software-does-blank-use" aria-label="Permalink to &quot;Which open source software does Blank use?&quot;">​</a></h2><p>Blank is open source itself, and builds on the work of many others: its fonts, the editor, the layout engine and their libraries. The <a href="https://github.com/FPurchess/blank/blob/main/public/THIRD-PARTY-NOTICES.txt" target="_blank" rel="noreferrer">third-party notices</a> list them all, with their licences.</p><h2 id="i-found-a-bug-or-have-an-idea" tabindex="-1">I found a bug or have an idea <a class="header-anchor" href="#i-found-a-bug-or-have-an-idea" aria-label="Permalink to &quot;I found a bug or have an idea&quot;">​</a></h2><p>Please <a href="https://github.com/FPurchess/blank/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a> on GitHub. If something went wrong, the end of Blank&#39;s <a href="#log">log</a> helps us find out why.</p><h2 id="log" tabindex="-1">Where is Blank&#39;s log? <a class="header-anchor" href="#log" aria-label="Permalink to &quot;Where is Blank&#39;s log? {#log}&quot;">​</a></h2><p>Blank writes down what goes wrong, like a file it couldn&#39;t save or an export that failed, in a log on your computer. It never sends it anywhere: you decide whether to share it, for example by pasting the end of it into an issue. The log names the files Blank worked with, with their folders, but never holds what you wrote.</p><p>You find it here:</p><table tabindex="0"><thead><tr><th>System</th><th>Log</th></tr></thead><tbody><tr><td>Linux</td><td><code>~/.local/share/com.github.fpurchess.blank/logs/blank.log</code> (or under <code>$XDG_DATA_HOME</code>, if set)</td></tr><tr><td>Linux, the Snap</td><td><code>~/snap/blank/current/.local/share/com.github.fpurchess.blank/logs/blank.log</code></td></tr><tr><td>macOS</td><td><code>~/Library/Logs/com.github.fpurchess.blank/blank.log</code></td></tr><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\com.github.fpurchess.blank\\logs\\blank.log</code></td></tr></tbody></table><p>The <code>~/.local</code> and <code>~/Library</code> folders are hidden: in the file manager, press <code>Ctrl</code> <code>H</code> on Linux, or choose <strong>Go → Go to Folder…</strong> in the Finder and paste the path. On Windows, paste the path into the address bar of the Explorer.</p><p>Each line says when, in UTC, and how serious it was. Once <code>blank.log</code> reaches 1 MB it is kept as an older file next to it, with its date in the name, and only the two newest of those stay, so the log never takes more than about 3 MB. You can delete the files at any time.</p>',28)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
